UPDATE locales_quest SET title_loc4="<UNUSED>", details_loc4="", Objectives_loc4="" WHERE entry=798;
UPDATE locales_quest SET title_loc4="<UNUSED>", details_loc4="", Objectives_loc4="" WHERE entry=799;
