UPDATE locales_quest SET title_loc4="联合团声望测试", details_loc4="", Objectives_loc4="" WHERE entry=9285;
UPDATE locales_quest SET title_loc4="占星者阵营", details_loc4="", Objectives_loc4="" WHERE entry=9286;
UPDATE locales_quest SET title_loc4="圣骑士训练", details_loc4="", Objectives_loc4="" WHERE entry=9287;
UPDATE locales_quest SET title_loc4="猎人训练", details_loc4="", Objectives_loc4="" WHERE entry=9288;
UPDATE locales_quest SET title_loc4="战士训练", details_loc4="", Objectives_loc4="" WHERE entry=9289;
