UPDATE locales_quest SET title_loc4="远离防御者之路", details_loc4="", Objectives_loc4="" WHERE entry=11106;
UPDATE locales_quest SET title_loc4="莫格霍尔大王", details_loc4="我知道我身份低微，根本没有资格直接带口信给您。请您原谅我的无礼。莫格霍尔大王要您立刻转至他的房间接受觐见。", Objectives_loc4="与影月谷龙喉营地的莫格霍尔大王谈一谈。" WHERE entry=11107;
UPDATE locales_quest SET title_loc4="伊利丹·怒风大人", details_loc4="来吧，大领主$N。伊利丹大人正等着你呢！", Objectives_loc4="与伊利丹·怒风会面。如果你有幸活下来，就转至沙塔斯城的贫民窟寻找巴萨姆斯。" WHERE entry=11108;
UPDATE locales_quest SET title_loc4="约鲁斯，蓝色灵翼幼龙", details_loc4="", Objectives_loc4="" WHERE entry=11109;
UPDATE locales_quest SET title_loc4="玛尔法斯，紫色灵翼幼龙", details_loc4="", Objectives_loc4="" WHERE entry=11110;
UPDATE locales_quest SET title_loc4="奥尼克森，黑色灵翼幼龙", details_loc4="", Objectives_loc4="" WHERE entry=11111;
UPDATE locales_quest SET title_loc4="苏拉库，青色灵翼幼龙", details_loc4="", Objectives_loc4="" WHERE entry=11112;
UPDATE locales_quest SET title_loc4="沃兰纳库，红色灵翼幼龙", details_loc4="", Objectives_loc4="" WHERE entry=11113;
