UPDATE locales_npc_text SET Text0_0_loc4="你可以去链金房看看。那是赫伯特·哈尔希医生和马许医生练习的地方。", Text0_1_loc4="你可以去链金房看看。那是赫伯特·哈尔希医生和马许医生练习的地方。"  WHERE entry=3528;
UPDATE locales_npc_text SET Text0_0_loc4="内环军事区的詹姆士·范·布朗特。", Text0_1_loc4="内环军事区的詹姆士·范·布朗特。"  WHERE entry=3529;
UPDATE locales_npc_text SET Text0_0_loc4="贸易区的那个尤奈斯·伯奇。", Text0_1_loc4="贸易区的那个尤奈斯·伯奇。"  WHERE entry=3530;
UPDATE locales_npc_text SET Text0_0_loc4="你到链金房的内环去。拉文尼亚在那里出没。", Text0_1_loc4="你到链金房的内环去。拉文尼亚在那里出没。"  WHERE entry=3531;
