UPDATE locales_npc_text SET Text0_0_loc4="接下来你必须和泰姆·狂暴图腾谈谈，他就在猎人高地。", Text0_1_loc4="接下来你必须和泰姆·狂暴图腾谈谈，他就在猎人高地。"  WHERE entry=7505;
