UPDATE locales_npc_text SET Text0_0_loc4="你好，年轻的萨满。在我的沙洲内就把这里当自己的家吧。", Text0_1_loc4="你好，年轻的萨满。在我的沙洲内就把这里当自己的家吧。"  WHERE entry=9014;
