UPDATE locales_npc_text SET Text0_0_loc4="你做了一件伟大的事，$N。这里任何时候都欢迎你。", Text0_1_loc4="你做了一件伟大的事，$N。这里任何时候都欢迎你。"  WHERE entry=9016;
UPDATE locales_npc_text SET Text0_0_loc4="来补充一些铁匠的物资，对吧?", Text0_1_loc4="来补充一些铁匠的物资，对吧?"  WHERE entry=9019;
UPDATE locales_npc_text SET Text0_0_loc4="我有新鲜的肉，鱼，和蘑菇。还有一大堆饮料!", Text0_1_loc4="我有新鲜的肉，鱼，和蘑菇。还有一大堆饮料!"  WHERE entry=9020;
