UPDATE locales_npc_text SET Text0_0_loc4="欢迎来到索尔玛，$N!你持续帮助我们的事业，我就会让你使用更多我们的物资。", Text0_1_loc4="欢迎来到索尔玛，$N!你持续帮助我们的事业，我就会让你使用更多我们的物资。"  WHERE entry=9023;
