UPDATE locales_npc_text SET Text0_0_loc4="女飞行师·薄暮站在博学者之门的外边靠近银月城，照顾龙鹰。", Text0_1_loc4="女飞行师·薄暮站在博学者之门的外边靠近银月城，照顾龙鹰。"  WHERE entry=10181;
