UPDATE locales_npc_text SET Text0_0_loc4="...sie haben uns gewarnt... aber wir gingen trotzdem... sie haben uns gewarnt... aber wir gingen trotzdem..", Text0_1_loc4="...sie haben uns gewarnt... aber wir gingen trotzdem... sie haben uns gewarnt... aber wir gingen trotzdem..."  WHERE entry=10201;
