UPDATE locales_npc_text SET Text0_0_loc4="我们的仓库已经见底了。除非我们能弄到更多的补给品，要不然我什么都没得卖。", Text0_1_loc4="我们的仓库已经见底了。除非我们能弄到更多的补给品，要不然我什么都没得卖。"  WHERE entry=13502;
