UPDATE locales_npc_text SET Text0_0_loc4="这是通往风暴之眼战场的传送门。", Text0_1_loc4="这是通往风暴之眼战场的传送门。"  WHERE entry=13577;
UPDATE locales_npc_text SET Text0_0_loc4="你的等级还不足以参加暴风之眼的战斗。等你获得更多经验的时候再回来。", Text0_1_loc4="你的等级还不足以参加暴风之眼的战斗。等你获得更多经验的时候再回来。"  WHERE entry=13578;
