UPDATE locales_npc_text SET Text0_0_loc4="这些元素的力量没有那么强大，凯莱丝和他的角鹰兽一定是被其他的东西给击落的。", Text0_1_loc4="这些元素的力量没有那么强大，凯莱丝和他的角鹰兽一定是被其他的东西给击落的。"  WHERE entry=14276;
