UPDATE locales_npc_text SET Text0_0_loc4="别急，$r!$B$B只有铁炉堡勇士才有办法购买我卖的东西。", Text0_1_loc4="别急，$r!$B$B只有铁炉堡勇士才有办法购买我卖的东西。"  WHERE entry=14457;
