UPDATE locales_npc_text SET Text0_0_loc4="沙玛巴觉得你找错军需官了!$B$B她的东西只卖给森金勇士...", Text0_1_loc4="沙玛巴觉得你找错军需官了!$B$B她的东西只卖给森金勇士..."  WHERE entry=14464;
