UPDATE locales_npc_text SET Text0_0_loc4="本地的裁缝是乔瑟夫·格里高利。他就在魔法区的内环。", Text0_1_loc4="本地的裁缝是乔瑟夫·格里高利。他就在魔法区的内环。"  WHERE entry=14925;
