UPDATE locales_npc_text SET Text0_0_loc4="愿圣光保护你，$c。", Text0_1_loc4="愿圣光保护你，$c。"  WHERE entry=16489;
UPDATE locales_npc_text SET Text0_0_loc4="日光照亮智慧之道。朋友，今日我等将踏向何处?", Text0_1_loc4="日光照亮智慧之道。朋友，今日我等将踏向何处?"  WHERE entry=16490;
UPDATE locales_npc_text SET Text0_0_loc4="愿日光保护你，$c。", Text0_1_loc4="愿日光保护你，$c。"  WHERE entry=16491;
UPDATE locales_npc_text SET Text0_0_loc4="我不管成功的机率有多低。就算只能够解救一个狼人脱离森林里残暴疯狂的生活，我们的努力就不算白费。", Text0_1_loc4="我不管成功的机率有多低。就算只能够解救一个狼人脱离森林里残暴疯狂的生活，我们的努力就不算白费。"  WHERE entry=16498;
UPDATE locales_npc_text SET Text0_0_loc4="哭嚎的亡者寻求安息，他们的苦痛在风中回荡。", Text0_1_loc4="哭嚎的亡者寻求安息，他们的苦痛在风中回荡。"  WHERE entry=16499;
UPDATE locales_npc_text SET Text0_0_loc4="这么快就回来了?", Text0_1_loc4="这么快就回来了?"  WHERE entry=16500;
UPDATE locales_npc_text SET Text0_0_loc4="我宁可酿酒胜过打架!$B$B但是运气好的话，说不定我两者都可以兼顾?", Text0_1_loc4="我宁可酿酒胜过打架!$B$B但是运气好的话，说不定我两者都可以兼顾?"  WHERE entry=16505;
UPDATE locales_npc_text SET Text0_0_loc4="愿大地祝福你。", Text0_1_loc4="愿大地祝福你。"  WHERE entry=16506;
UPDATE locales_npc_text SET Text0_0_loc4="我们不能让那些真菌惧兽靠近前线，它们太强大了!", Text0_1_loc4="我们不能让那些真菌惧兽靠近前线，它们太强大了!"  WHERE entry=16507;
UPDATE locales_npc_text SET Text0_0_loc4="我父亲就在附近，我知道!我们一定得冲破他们的防线，把他救出来!", Text0_1_loc4="我父亲就在附近，我知道!我们一定得冲破他们的防线，把他救出来!"  WHERE entry=16508;
