UPDATE locales_npc_text SET Text0_0_loc4="欢迎来到多兰纳尔，$c。若是需要任何食谱或食材，敬请告诉我。", Text0_1_loc4="欢迎来到多兰纳尔，$c。若是需要任何食谱或食材，敬请告诉我。"  WHERE entry=16510;
