UPDATE locales_npc_text SET Text0_0_loc4="睁大你的双眼，$c。就连杜洛塔也正受到敌人的威胁。", Text0_1_loc4="睁大你的双眼，$c。就连杜洛塔也正受到敌人的威胁。"  WHERE entry=16535;
