UPDATE locales_npc_text SET Text0_0_loc4="很高兴你成功了，$n。", Text0_1_loc4="很高兴你成功了，$n。"  WHERE entry=16542;
UPDATE locales_npc_text SET Text0_0_loc4="派比蛋糕要好吃多了，大家都知道!像你这样身分地位的$C，难道连这么重要的事情也不晓得吗?", Text0_1_loc4="派比蛋糕要好吃多了，大家都知道!像你这样身分地位的$C，难道连这么重要的事情也不晓得吗?"  WHERE entry=16543;
