UPDATE locales_npc_text SET Text0_0_loc4="嗯?", Text0_1_loc4="嗯?"  WHERE entry=16732;
UPDATE locales_npc_text SET Text0_0_loc4="你怎么有办法徒步活着来到这里?你必定是个勇敢的英雄，竟然冒险来到厄运之槌。", Text0_1_loc4="你怎么有办法徒步活着来到这里?你必定是个勇敢的英雄，竟然冒险来到厄运之槌。"  WHERE entry=16733;
