UPDATE locales_npc_text SET Text0_0_loc4="桌上有几堆补给品。你决定先拿座狼皮。", Text0_1_loc4="桌上有几堆补给品。你决定先拿座狼皮。"  WHERE entry=17383;
UPDATE locales_npc_text SET Text0_0_loc4="你看到了几叠你之前收集的座狼皮。这些皮革可以拿来缝制你要的伪装。", Text0_1_loc4="你看到了几叠你之前收集的座狼皮。这些皮革可以拿来缝制你要的伪装。"  WHERE entry=17384;
