UPDATE locales_npc_text SET Text0_0_loc4="把事情作个了结，让这些家伙出发去。我还有个任务在等着呢。", Text0_1_loc4="把事情作个了结，让这些家伙出发去。我还有个任务在等着呢。"  WHERE entry=17669;
UPDATE locales_npc_text SET Text0_0_loc4="继续前进，朋友。$b$b等我力量恢复了，我会自己想办法出去的。", Text0_1_loc4="继续前进，朋友。$b$b等我力量恢复了，我会自己想办法出去的。"  WHERE entry=17670;
