REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (561,0,'什么是“地下矩阵”？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (562,0,'土灵是什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (563,0,'你所说的异常是指什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (564,0,'什么是“基础弹性建设”？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (565,0,'因此……土灵是从石头中诞生的？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (566,0,'关于土灵还有什么我应该知道的？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (567,0,'我想现在我明白了造物者设计土灵的意图了。你之前说到的土地异常是什么情况？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (568,0,'什么！？高压力环境会导致大地破碎。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (569,0,'当大地破碎时发生了什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (570,0,'穴居人？！你提到的穴居人和现在世界上的一个种族是同一个吗？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (571,0,'当土灵不稳定时，你提到的两个结果。第二个是什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (572,0,'矮人！！你是说矮人是由土灵进化来的？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (573,0,'这些矮人会有一天是相同的，对吗？矮人和土灵还保持着其它联系吗？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (574,0,'谁是创造者？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (575,0,'这已经足够去思考了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (576,0,'我会立刻使用光碟。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (581,0,'训练我');
