REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3666,0,'篡位者？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3667,0,'恕我直言，统帅大人--为什么不消灭他们？难道这不会巩固我们的地位吗？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3668,0,'我……我可不这样想，战争之王。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3669,0,'我活着就是为了为战争之王服务！没有你的指导，我的生活将空虚而无意义。');
