REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3682,0,'那可真糟糕。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3683,0,'我会的，提里奥。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3701,2,'你明说吧，尼尔鲁……');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (3801,0,'我准备好接受幻象了，麦兰达。');
