REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (6534,0,'你好，弗兰卡。我听说你知道纳塔莉亚的下落。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (6535,0,'像参加盛会那样打扮我！');
