REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (6540,4,'苍白圣殿骑士！我手中握着你的召唤纹章。响应我的召唤吧！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (6542,0,'卑鄙的公爵，听好了！我可不是暮光之锤的走狗！我是来向你提出挑战的！来吧，受死吧……');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (6542,1,'灰烬公爵！我手中握着你的徽记！响应我的召唤吧！');
