REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7481,0,'不给糖就捣蛋！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7481,1,'把旅店设为我的家。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7481,2,'我想要浏览你的货物。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7482,0,'听着，人类。我不关心你们的约定，但是你们有我要的东西。告诉我在哪里可以找到血铸铁锭。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7484,0,'我如何完成工会表格？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7484,1,'我想要建立工会。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7486,0,'拿走血骑士的徽记。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7495,0,'观察者莉萨奥，你在这里做什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7497,0,'没有糖果就捣乱！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7497,1,'将这座旅店设为你的家。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7497,2,'我想要看看你卖的货物。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7499,1,'我们准备好了，萨尔。我们走吧！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7502,0,'是的。请继续。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7503,0,'请吧，如果你不介意。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7504,0,'预言者努波顿, 请继续。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7505,0,'它对你说了些什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7506,0,'那是什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7507,0,'你做了些什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7508,0,'请继续。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7517,0,'训练我。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7517,1,'我想要遗忘我的天赋。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7520,0,'好吧，我会放你出去。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7522,0,'教我圣光之路');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7522,1,'我想要重置天赋。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7524,0,'我想要浏览你的货物。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7531,0,'我是一名囚犯，它看起来像什么？在我离开太阳之门后，德莱尼就抓住了我。他们杀死了传送门控制者，摧毁了大门。太阳王对发生的这一切非常不满。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7533,0,'我信了，你也相信我。你的信息对我很有用，血精灵。你帮助了我们很多。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7534,0,'矢量感应器非常巨大。我希望我们能有更多的畸变者去看守其它几个弱点。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7535,0,'希隆娜丝是一名艾瑞达人……是的……我是说……很明显……');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7536,0,'难以置信。希隆娜丝是怎么完成的？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7537,0,'啊，对，希隆娜丝。我都快忘了希隆娜丝在这儿了。我在外域服侍希隆娜丝。不过我还没听说这么可憎的事情，当我在这世界还不是完全体的时候，可恶的德莱尼就抓住我了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7540,0,'博学的长者，请给我你的祝福。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7552,0,'我和我的伙伴们将与您并肩作战，普罗德摩尔女士。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7552,1,'我们已经准备好对付阿克蒙德的任何爪牙了，普罗德摩尔女士。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7552,2,'再会，普罗德摩尔女士。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7559,0,'赐予我你的印记吧，睿智的古树。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7559,1,'赐予我你的印记吧，睿智的古树。');
