REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7566,0,'这是我一直追求的术士之道。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7566,1,'我想要重置天赋。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7567,0,'我要德鲁伊的训练。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7567,1,'我想要重置天赋。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7571,0,'我希望遗忘药水专精。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7571,1,'我打算重新接受炼金师训练。我希望在药水制作方面有所专精。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7579,0,'赫米特·奈辛瓦里，你在这里做些什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7581,0,'我们无所畏惧。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7581,1,'我与你并肩作战，萨尔。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7581,2,'再会，萨尔。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7582,0,'你好，长者。该和你的人民一起取消对德莱尼及其盟友的敌意了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7583,0,'我不是有意欺骗你的，长老。泰雷多尔的德莱尼想用这种可能和你们有点像的方式接近你们。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7585,0,'我会转告他们的。再见，长老。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7588,0,'让我看看你的货物，玛克图。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7589,0,'我想看看你的货物。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7590,0,'让我看看你的材料和毒药补给。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7590,1,'专家，嗯？那么你是哪一方面的专家？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7596,0,'我只在低语中听到过你的名字，法师。你是谁？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7611,0,'我要从你那儿买东西。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7612,0,'我想从你那里购物。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7628,0,'我想从你这儿买点东西。');
