REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7668,0,'向西走。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7668,1,'向东走。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7669,0,'我需要答案，食人魔！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7671,0,'这意味着战争，拉普！我说的是战争！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7672,0,'你以为你可以想吃什么就吃什么吗？你肯定是想去吃塔拉的破碎者。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7673,0,'为什么石拳氏族出现在这么远的地方？你要知道这是库雷尼的领地。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7675,0,'我已经杀了很多你说的食人魔，兰特瑞索。我并不害怕。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7675,1,'我杀了你们这么多食人魔，兰特瑞索。我什么都不怕。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7676,0,'我需要做什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7677,0,'那我们只能抗争到底，兰特瑞索。我不会眼睁睁地看着你掠夺我们的城镇，杀害我们的人民。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7678,0,'我们希望你能将石拳兽人后撤，离开我的领地。相应地，我们也会将部队撤回来。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7679,0,'很抱歉，我无意冒犯。我为我的人民而来。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7680,0,'我听说过你这一族，但从未想到能亲眼见到混血龙类。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7681,0,'另一半呢？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7682,0,'我应该知道吗？对我来说你看起来像一个兽人。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7690,0,'训练我');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7691,0,'训练我');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7704,0,'埃博尔，你得告诉我是怎么回事，我得知道！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7704,1,'把你知道的再跟我讲一遍！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7706,0,'女祭司，无论你给予我什么样的帮助，我都会感激你的。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7713,0,'让我看看你的货物。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7715,0,'熔炉营地？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7716,0,'你现在怎么看他们？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7717,0,'现在呢？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7718,0,'军团？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7719,0,'我看到扭曲的钢铁，嗅到了分裂的大地。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7719,1,'告诉我更多关于在卡拉波废墟训练场的恶魔猎人的事情。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7719,2,'准备调查这个地方。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7722,0,'给我军旗。我会控制双塔废墟的。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7722,1,'我要兑换印记！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7724,0,'给我军旗。我会控制双塔废墟的。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7724,1,'我要兑换印记！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7725,0,'奥图里斯派我过来的。他说你能帮我。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7729,0,'我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7730,0,'我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7731,0,'他想要“金币”。再说一次……要么付钱要么纳命来……');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7732,0,'我是萨萨拉比姆派来收债的。还钱，否则我就不客气了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7735,0,'沙塔尔是谁？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7735,1,'沙塔斯不是一座德莱尼的城市嘛？为什么允许其他人在这儿？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7757,0,'你为什么要把这堆东西修起来？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7759,0,'你在这里做什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7760,0,'最近有什么新闻，顾问？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7762,0,'不过我还没听说这么可憎的事情，当我在这世界还不是完全体的时候，可恶的德莱尼就抓住我了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7763,0,'职责是什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7764,0,'离开？为什么会选择离开？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7765,0,'怎么办？我已经尝试过很多方法了。我尽全力帮助我在纳格兰的人民。每次我接近加尔鲁什，他都对我不屑一顾。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7766,0,'你信吗？');
