REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7768,1,'加尔鲁什无可救药了，祖母。我在帮助玛格汉的时候就担心这件事情了，我认为加尔鲁什不适合做一个领导者。');
