REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7967,3,'我正在为前线指挥官托尔克执行轰炸任务。我需要一头武装飞龙！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7967,4,'借我一只驭风者，我要去断脊者营地！');
