REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7970,3,'我正在执行前线指挥官金斯顿下达的轰炸任务。我需要一头武装狮鹫！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7970,4,'送我去破碎岗哨！');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7974,0,'我已经尽力了，祖母。谢谢你的忠告。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7976,0,'我即将返回艾泽拉斯，祖母。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7977,0,'这是我的酋长，祖母。人民——来自我的世界——的领导者……杜隆坦的儿子，您的孙子。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7978,0,'祖母，我从未感到荣耀。杜隆坦已经战死很久了，但是他的英勇事迹广为我的世界所知。兽人居住在名为杜隆塔尔——以您的儿子为名——的地方。并且……<你呼了几口气，想了一下接下来要告诉祖母的事情。>');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7979,0,'祖母，你是杜隆坦的母亲？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (7981,0,'我弄丢了大法师瓦格斯的法杖。');
