REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8011,0,'然后你是怎么做的？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8012,0,'当时发生什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8013,0,'我明白了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8014,0,'我还有些别的事情想问你。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8021,0,'让我看看你都卖些什么。');
