REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8031,0,'我想从你这儿买点东西。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8033,0,'艾泽基尔说他有某本书……');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8034,0,'让我们看看你的能力吧。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8040,0,'乌提斯？');
