REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8062,0,'试图联络星界商人玛里德。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8062,1,'尝试联系星界商人玛里德。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8063,0,'你都提供些什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8070,0,'你都卖些什么？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8071,0,'星界商人玛里德。我带着更多关于虚空龙的消息回来了，我想和你做个交易——为了挣笔外快。我会照顾好那个麻烦的暗夜精灵和她的人类朋友。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8072,0,'请将我带到主人的巢穴。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8077,0,'我想去战场。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8081,0,'魔导师卡尔琳达派我来问你关于阿兰里昂的秘密。他看到了谁？');
