REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (8339,0,'我需要去考虑所有的细节吗？我想我们都很清楚伊利丹大人对那些反对者做了什么，我必须走了。再见，鲁斯克，永远…………');
