REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15014,0,'你是说你是一条龙吗？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15015,0,'是的，拜托了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15016,0,'告诉我。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15017,0,'不过死亡之翼已经走了。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15018,0,'继续');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15019,0,'那你怎么不做呢？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15020,0,'除非');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15021,0,'我该怎么做？');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (15022,0,'继续。');
REPLACE INTO locales_gossip_menu_option (menu_id, id, option_text_loc4) VALUES (19606,0,'葛雷克，你要试试拉克妮亚刚调配出来的武器油吗？');
