UPDATE script_texts SET content_loc4="好吧，好吧！拉普投降！" WHERE entry=-1000192 ;
UPDATE script_texts SET content_loc4="%s低头看着地上的项链。女王带着悲伤的神情吟唱了一段咒语，召唤出上层精灵的灵魂。整个房间中都回响着辛多雷那久远的歌声……" WHERE entry=-1000193 ;
UPDATE script_texts SET content_loc4="我投降！不要杀我！" WHERE entry=-1000194 ;
UPDATE script_texts SET content_loc4="Belore……" WHERE entry=-1000196 ;
UPDATE script_texts SET content_loc4="%s叹了口气，跪下身捡起了护符。" WHERE entry=-1000197 ;
UPDATE script_texts SET content_loc4="看招，混帐！" WHERE entry=-1000198 ;
UPDATE script_texts SET content_loc4="请告诉我你没有做那件我认为你刚刚做了的事情。请告诉我……我不必对你动手……" WHERE entry=-1000199 ;
UPDATE script_texts SET content_loc4="难道我们的麻烦还不够多吗？你还要火上浇油？！" WHERE entry=-1000200 ;
UPDATE script_texts SET content_loc4="我得救了！谢谢你，医生！" WHERE entry=-1000201 ;
UPDATE script_texts SET content_loc4="万岁！我得救了！" WHERE entry=-1000202 ;
UPDATE script_texts SET content_loc4="亲爱的，拥抱我……拥抱我……" WHERE entry=-1000203 ;
UPDATE script_texts SET content_loc4="%s疑惑地看着你。或许你该仔细看看？" WHERE entry=-1000204 ;
UPDATE script_texts SET content_loc4="%s充满期待地看着你。" WHERE entry=-1000205 ;
UPDATE script_texts SET content_loc4="嗯。渴死我了！" WHERE entry=-1000207 ;
UPDATE script_texts SET content_loc4="哦，看！血槌啤酒！唔……" WHERE entry=-1000208 ;
UPDATE script_texts SET content_loc4="警告！%s的紧急停机程序已经启动。停机将在两分钟内完成。" WHERE entry=-1000211 ;
UPDATE script_texts SET content_loc4="将在一分钟后完成紧急停机。" WHERE entry=-1000212 ;
UPDATE script_texts SET content_loc4="将在三十秒后紧急停机。" WHERE entry=-1000213 ;
UPDATE script_texts SET content_loc4="将在十秒后紧急停机。" WHERE entry=-1000214 ;
