UPDATE script_texts SET content_loc4="我还钱！我还钱！呀～！不要伤害我！" WHERE entry=-1000604 ;
UPDATE script_texts SET content_loc4="把我的宝藏拿去吧……这样天气就会好转……亡灵也会离开。" WHERE entry=-1000615 ;
UPDATE script_texts SET content_loc4="我们把闪闪发光的宝贝都供奉给了神殿……我们一点也不贪心啊……为什么会这样？" WHERE entry=-1000616 ;
UPDATE script_texts SET content_loc4="我做错事了？对不起……" WHERE entry=-1000617 ;
UPDATE script_texts SET content_loc4="我们……什么都没做啊……我搞不明白。" WHERE entry=-1000618 ;
UPDATE script_texts SET content_loc4="谢谢……你。" WHERE entry=-1000619 ;
UPDATE script_texts SET content_loc4="请收下……我亮闪闪的财宝。结束了……" WHERE entry=-1000620 ;
UPDATE script_texts SET content_loc4="%s开始收集迁跃追迹者的血液。" WHERE entry=-1000625 ;
UPDATE script_texts SET content_loc4="%s吃着刚被杀死的迁跃追迹者。" WHERE entry=-1000628 ;
UPDATE script_texts SET content_loc4="<咳嗽><咳嗽>这里有个痛苦的年轻姑娘！" WHERE entry=-1000629 ;
UPDATE script_texts SET content_loc4="嘿？帮个忙行不行？" WHERE entry=-1000630 ;
UPDATE script_texts SET content_loc4="不要把我留在这里！要是你这么绝情，我做鬼也不会放过你……" WHERE entry=-1000631 ;
UPDATE script_texts SET content_loc4="好吧，我们离开这里！" WHERE entry=-1000632 ;
UPDATE script_texts SET content_loc4="你确信你准备好了？再等一会儿。" WHERE entry=-1000633 ;
UPDATE script_texts SET content_loc4="好吧，我们出发吧！" WHERE entry=-1000634 ;
UPDATE script_texts SET content_loc4="痛！我不干了，我不要当靶子！" WHERE entry=-1000644 ;
UPDATE script_texts SET content_loc4="耳朵！你弄伤了我的耳朵！" WHERE entry=-1000645 ;
UPDATE script_texts SET content_loc4="我的胡子！两边不对称了！" WHERE entry=-1000646 ;
UPDATE script_texts SET content_loc4="好准！" WHERE entry=-1000647 ;
UPDATE script_texts SET content_loc4="别抱怨了。你的运气还不错啊。" WHERE entry=-1000648 ;
UPDATE script_texts SET content_loc4="呸，还是有进步的。" WHERE entry=-1000649 ;
UPDATE script_texts SET content_loc4="冷静点，伙计。这只是小号铅弹啊！" WHERE entry=-1000650 ;
UPDATE script_texts SET content_loc4="只是有点伤自尊嘛，伙计。振作一点啦！" WHERE entry=-1000651 ;
UPDATE script_texts SET content_loc4="我太饿了！太好吃了！" WHERE entry=-1000652 ;
UPDATE script_texts SET content_loc4="嗨……我感觉不是太好。" WHERE entry=-1000653 ;
UPDATE script_texts SET content_loc4="你是个坏兽人……坏……啊！" WHERE entry=-1000654 ;
UPDATE script_texts SET content_loc4="开饭时间到了！？" WHERE entry=-1000655 ;
UPDATE script_texts SET content_loc4="它一口吞下了一只羊！" WHERE entry=-1000656 ;
UPDATE script_texts SET content_loc4="我能感受到你内心的阴影。邪恶的侵蚀永远不会停止！" WHERE entry=-1000666 ;
UPDATE script_texts SET content_loc4="让我吞噬你的灵魂吧！" WHERE entry=-1000667 ;
UPDATE script_texts SET content_loc4="%s将最后的力量灌注到附近的符石中，成功地激活了它。" WHERE entry=-1000668 ;
UPDATE script_texts SET content_loc4="我们会根据你收集的碎片找出梦魇的源头，$n。那样我们就能打开一条裂缝，把伊兰尼库斯从翡翠梦境中拉出来。要坚强，$C。我们将要邀请梦魇的化身进入我们的世界。" WHERE entry=-1000669 ;
UPDATE script_texts SET content_loc4="向永夜港前进！不要掉以轻心，勇士。" WHERE entry=-1000670 ;
UPDATE script_texts SET content_loc4="月神湖上空将出现一道裂缝。做好准备吧，$n。伊兰尼库斯的入侵会给整个世界带来混乱和战争。" WHERE entry=-1000671 ;
UPDATE script_texts SET content_loc4="他会不择手段地摧毁玛法里奥的肉身。我们绝不能让此事发生……我们必须在泰兰德到达之前控制住那头野兽。" WHERE entry=-1000672 ;
UPDATE script_texts SET content_loc4="保卫永夜港，英雄……" WHERE entry=-1000673 ;
UPDATE script_texts SET content_loc4="梦境之暴君伊兰尼库斯已经进入了我们的世界。" WHERE entry=-1000674 ;
UPDATE script_texts SET content_loc4="可怜的凡人……你都不知道自己在干什么！主人的愿望已经达成。月光林地和玛法里奥都会被摧毁的！" WHERE entry=-1000675 ;
UPDATE script_texts SET content_loc4="你这恶魔！尝尝塞纳留斯的力量吧！" WHERE entry=-1000676 ;
UPDATE script_texts SET content_loc4="%s露出阴险的笑容。" WHERE entry=-1000677 ;
UPDATE script_texts SET content_loc4="小子，你当然没法跟你的父亲相比。要是我高兴的话，我会一爪要了你的命。让怒风来挑战我，你就趁早躲到一边去吧。" WHERE entry=-1000678 ;
UPDATE script_texts SET content_loc4="你算错了一招，野兽。你不曾料到我们会在玛法里奥的身边召唤你吧？伊兰尼库斯，你的救赎就要来临了。你将得到净化——堕落之源将被清除。" WHERE entry=-1000679 ;
UPDATE script_texts SET content_loc4="救赎？大胆！只有我的神能救赎我。" WHERE entry=-1000680 ;
UPDATE script_texts SET content_loc4="%s疯狂地咆哮起来。" WHERE entry=-1000681 ;
UPDATE script_texts SET content_loc4="快，$n！我们必须尽快找地方躲起来！" WHERE entry=-1000682 ;
UPDATE script_texts SET content_loc4="勇士，请保护我们的人民吧！" WHERE entry=-1000683 ;
UPDATE script_texts SET content_loc4="出来吧，梦魇的仆从们！摧毁这世界！不留活口……" WHERE entry=-1000684 ;
UPDATE script_texts SET content_loc4="我们将一同对抗这些恶魔！永夜港的卫兵也加入了我们的队伍，他们将誓死抗敌。现在我们必须将这些疯狂的家伙赶回梦魇。消灭他们！" WHERE entry=-1000685 ;
UPDATE script_texts SET content_loc4="你们的救世主在哪儿？面对我的攻击，你还能支撑多久？" WHERE entry=-1000686 ;
UPDATE script_texts SET content_loc4="打败了我的手下？来跟我打打看吧，凡人！" WHERE entry=-1000687 ;
UPDATE script_texts SET content_loc4="雷姆洛斯，我不费吹灰之力就能了结他们。住手吧，愚蠢的家伙。把这个德鲁伊交给我来对付，我会很快结束战斗的……" WHERE entry=-1000688 ;
UPDATE script_texts SET content_loc4="艾露恩，请聆听我的祷告。让我们获得心灵的平静吧！注视着我们倒下的躯体吧……" WHERE entry=-1000689 ;
UPDATE script_texts SET content_loc4="姐妹们，照顾那些受伤的士兵！" WHERE entry=-1000690 ;
UPDATE script_texts SET content_loc4="伊兰尼库斯，寻求赦免吧。一切都会得到宽恕的……" WHERE entry=-1000691 ;
UPDATE script_texts SET content_loc4="伊兰尼库斯，你的罪行会被赦免的。艾露恩永远爱着你。挣脱禁锢着你的束缚吧！" WHERE entry=-1000692 ;
UPDATE script_texts SET content_loc4="上古之神的束缚没有丝毫减弱的迹象。他完全被他们黑暗的思想所控制……我……我不能……不能引导……帮帮我，艾露恩……" WHERE entry=-1000693 ;
UPDATE script_texts SET content_loc4="燃烧起来了！疼痛……灼热……" WHERE entry=-1000694 ;
UPDATE script_texts SET content_loc4="为什么？为什么……会发生这种事？泰兰德，你在哪儿？当我在月神面前倒下时，你在哪儿？" WHERE entry=-1000695 ;
UPDATE script_texts SET content_loc4="我……我感到……我再次感受到月神的触摸……她在对我微笑……是的……我……" WHERE entry=-1000696 ;
UPDATE script_texts SET content_loc4="梦境之暴君伊兰尼库斯被月神之光吞噬了。月光林地恢复了往日的宁静。" WHERE entry=-1000697 ;
UPDATE script_texts SET content_loc4="%s跪倒在地。" WHERE entry=-1000698 ;
UPDATE script_texts SET content_loc4="赞美艾露恩……伊兰尼库斯被拯救了。" WHERE entry=-1000699 ;
UPDATE script_texts SET content_loc4="我已经迷失很久了……梦魇令我完全堕落……现在……你们……你们拯救了我。是你们将我从梦魇的魔爪下解放出来。" WHERE entry=-1000700 ;
UPDATE script_texts SET content_loc4="但是……玛法里奥、塞纳留斯、伊瑟拉……他们还在坚持。他们需要我。我必须马上返回翡翠梦境。" WHERE entry=-1000701 ;
UPDATE script_texts SET content_loc4="我的女王，我不值得你亲自祈祷。你是光明的天使，希望的化身。请让我返回那个古老的洞穴，这样或许我就可以回到翡翠梦境。跟玛法里奥一样，我也有心爱的她……她在等着我……我必须回到她身边……保护她……" WHERE entry=-1000702 ;
UPDATE script_texts SET content_loc4="英雄……我有你要找的东西。愿它能再次为净化邪恶的力量而效劳。雷姆洛斯，请确保我们的勇士得到绿龙军团保管的碎片。" WHERE entry=-1000703 ;
UPDATE script_texts SET content_loc4="没问题，伊兰尼库斯。你要保重。" WHERE entry=-1000704 ;
UPDATE script_texts SET content_loc4="英雄，让我们离开永夜港吧。来小树林找我。" WHERE entry=-1000705 ;
UPDATE script_texts SET content_loc4="你所属的世界将陷入残酷的末日。噩梦已经降临！" WHERE entry=-1000706 ;
UPDATE script_texts SET content_loc4="这蓝色的亮光……真奇怪。你认为它意味着什么？" WHERE entry=-1000707 ;
UPDATE script_texts SET content_loc4="我们找到它了！" WHERE entry=-1000708 ;
UPDATE script_texts SET content_loc4="请在我吟唱的时候点亮这个。" WHERE entry=-1000709 ;
UPDATE script_texts SET content_loc4="就是这个地方。让我们点亮它。" WHERE entry=-1000710 ;
UPDATE script_texts SET content_loc4="我们再找下一个。" WHERE entry=-1000711 ;
UPDATE script_texts SET content_loc4="我们必须继续前进。" WHERE entry=-1000712 ;
UPDATE script_texts SET content_loc4="现在该进行最后一步了，我们必须激活祭坛。" WHERE entry=-1000713 ;
UPDATE script_texts SET content_loc4="我会阅读刻在石头上的字，而你必须想办法点亮它。" WHERE entry=-1000714 ;
UPDATE script_texts SET content_loc4="祭坛在发光！我们做到了！" WHERE entry=-1000715 ;
UPDATE script_texts SET content_loc4="发生什么了？看！" WHERE entry=-1000716 ;
UPDATE script_texts SET content_loc4="已经很多年了……" WHERE entry=-1000717 ;
UPDATE script_texts SET content_loc4="谁在女神的祭坛捣乱？" WHERE entry=-1000718 ;
UPDATE script_texts SET content_loc4="女祭司,请原谅我们的闯入。我们不想造成任何伤害。" WHERE entry=-1000719 ;
UPDATE script_texts SET content_loc4="我们只是希望知道枭兽为什么要守卫这片地区……" WHERE entry=-1000720 ;
UPDATE script_texts SET content_loc4="Enu thora'serador。这是一片神圣之地。" WHERE entry=-1000721 ;
UPDATE script_texts SET content_loc4="我们会给你看……" WHERE entry=-1000722 ;
UPDATE script_texts SET content_loc4="朝上看，Thara dormil dorah……" WHERE entry=-1000723 ;
UPDATE script_texts SET content_loc4="这宝石曾允许与月神本人进行直接沟通。" WHERE entry=-1000724 ;
UPDATE script_texts SET content_loc4="月神通过宝石传达着她无尽的智慧……" WHERE entry=-1000725 ;
UPDATE script_texts SET content_loc4="宝石需要得到保护，于是我们就向女神求助。" WHERE entry=-1000726 ;
UPDATE script_texts SET content_loc4="很快，我们眼前浮现出一种生物的幻象……它有猫头鹰的羽毛，同时也有熊的意志和力量……" WHERE entry=-1000727 ;
UPDATE script_texts SET content_loc4="就在那天我们得到了枭兽。凶猛的守卫，女神派枭兽保护她所有的神圣之地。" WHERE entry=-1000728 ;
UPDATE script_texts SET content_loc4="Anu'dorini Talah。Ru shallora enudoril。" WHERE entry=-1000729 ;
UPDATE script_texts SET content_loc4="但是现在，枭兽已经变得更加凶猛，而且由于失去了女神的指引，它们很迷茫……" WHERE entry=-1000730 ;
UPDATE script_texts SET content_loc4="它们毫无目的地游荡……但是很多枭兽又回到了它们曾经发誓要保护的神圣之地。" WHERE entry=-1000731 ;
UPDATE script_texts SET content_loc4="枭兽天生具有魔力；这种力量是由女神赐予他们的。" WHERE entry=-1000732 ;
UPDATE script_texts SET content_loc4="你要知道，无论身处何地，他们都会受他人委托，保护着某种重要的东西。" WHERE entry=-1000733 ;
UPDATE script_texts SET content_loc4="记住我们向你展示的……" WHERE entry=-1000734 ;
UPDATE script_texts SET content_loc4="再见。" WHERE entry=-1000735 ;
UPDATE script_texts SET content_loc4="谢谢你的帮助，$n。祝你探险顺利。" WHERE entry=-1000736 ;
UPDATE script_texts SET content_loc4="我想呆在这儿，思考一下所见的事情。找到艾瑞拉斯并告诉他我们学到的东西。" WHERE entry=-1000737 ;
UPDATE script_texts SET content_loc4="%s开始吟唱一个奇怪的法术……" WHERE entry=-1000738 ;
UPDATE script_texts SET content_loc4="记住，我需要你的帮助来正确进行吟唱。我在我们前进的路上会请你帮好几次忙，所以请准备好。" WHERE entry=-1000739 ;
UPDATE script_texts SET content_loc4="我们必须赶快行动。奥伯丁离这里不远，但是有很多敌人潜伏在森林里。" WHERE entry=-1000771 ;
UPDATE script_texts SET content_loc4="似乎我们遇到麻烦了。打起精神来，他们来了！" WHERE entry=-1000772 ;
UPDATE script_texts SET content_loc4="刺客……最好在他们找到我们之前快点离开这里。" WHERE entry=-1000773 ;
UPDATE script_texts SET content_loc4="小心！我感到附近有邪恶的存在……亡灵！" WHERE entry=-1000774 ;
UPDATE script_texts SET content_loc4="一个圣骑士！杀死他的话，主人会很高兴的。进攻！" WHERE entry=-1000775 ;
UPDATE script_texts SET content_loc4="我们继续前进吧，否则会碰到更多想要我命的东西。" WHERE entry=-1000776 ;
UPDATE script_texts SET content_loc4="又是这三个？" WHERE entry=-1000777 ;
UPDATE script_texts SET content_loc4="净化者德尔格伦不在的时候你好像不太自信，不是吗？" WHERE entry=-1000778 ;
UPDATE script_texts SET content_loc4="这次我会把你彻底干掉！" WHERE entry=-1000779 ;
UPDATE script_texts SET content_loc4="干得好！我应该可以自己离开这里了。记着到灰谷的梅伊瑟娜岗哨去和净化者德尔格伦谈谈。" WHERE entry=-1000780 ;
UPDATE script_texts SET content_loc4="谢谢你，$n。现在让我们离开这儿！" WHERE entry=-1000784 ;
UPDATE script_texts SET content_loc4="我们成功了！再次感谢你！我先走了！" WHERE entry=-1000785 ;
UPDATE script_texts SET content_loc4="嗨，霍恩尼兹！我回来了！有些好心人帮我脱离了困境。" WHERE entry=-1000786 ;
UPDATE script_texts SET content_loc4="我们不得不把玛洛迪半人马从我们的合作伙伴列表中划掉。他们太难共事了……" WHERE entry=-1000787 ;
UPDATE script_texts SET content_loc4="好吧，我要到吉尔吉斯村去了。他们不像玛洛迪半人马一样蠢，而且他们更加通情达理。" WHERE entry=-1000788 ;
UPDATE script_texts SET content_loc4="嗷！好吧，我回去工作，$n！" WHERE entry=-1000795 ;
UPDATE script_texts SET content_loc4="好困...太困了..." WHERE entry=-1000796 ;
UPDATE script_texts SET content_loc4="%s叫喊着冲向沙拉斯鸦巢。快点跟上去！" WHERE entry=-1000797 ;
UPDATE script_texts SET content_loc4="%s在树前短暂地停了一下，然后直接向里面冲了进去。" WHERE entry=-1000798 ;
UPDATE script_texts SET content_loc4="%s似乎正在寻找什么东西。它想让你跟着它。" WHERE entry=-1000799 ;
UPDATE script_texts SET content_loc4="%s飞到了平台下方！如果你不想跟它走失，最好直接跳下去，快一点！" WHERE entry=-1000800 ;
UPDATE script_texts SET content_loc4="%s发出了一声巨吼！" WHERE entry=-1000801 ;
UPDATE script_texts SET content_loc4="终于摆脱了那可恶的诅咒了！谢谢你！请给救赎者瑞拉克带个口信。我在斯克提斯还有任务，必须消灭泰罗克！" WHERE entry=-1000802 ;
UPDATE script_texts SET content_loc4="你不是一个人在战斗，你不是一个人，$n！让我们一起放逐这地狱之火的子嗣！" WHERE entry=-1000803 ;
UPDATE script_texts SET content_loc4="你准备好了我们就开战。" WHERE entry=-1000804 ;
UPDATE script_texts SET content_loc4="我们会用武力把元素之灵从你的魔掌中解救出来！" WHERE entry=-1000805 ;
UPDATE script_texts SET content_loc4="元素们说了些什么，托洛克？我什么都没听到。" WHERE entry=-1000806 ;
UPDATE script_texts SET content_loc4="我听到的和你一样，兄弟。看看你身后……" WHERE entry=-1000807 ;
UPDATE script_texts SET content_loc4="他们得到了救赎！那么我们胜利了？" WHERE entry=-1000808 ;
UPDATE script_texts SET content_loc4="就应该是现在这样，萨满祭司。你干得不错。" WHERE entry=-1000809 ;
UPDATE script_texts SET content_loc4="是的……对这里的元素来说，已经很好了，但是密码已经被别人知道了……火焰之灵正在骚动……如果不阻止这股力量，这些凡人所属的世界将会灭亡。" WHERE entry=-1000810 ;
UPDATE script_texts SET content_loc4="保重，凡人……大地治愈者了解火焰之灵的感受……" WHERE entry=-1000811 ;
UPDATE script_texts SET content_loc4="那么我们走了，托洛克。我只有一个要求……" WHERE entry=-1000812 ;
UPDATE script_texts SET content_loc4="欧鲁诺克·裂心等人把他们的武器交给了大地治愈者托洛克。" WHERE entry=-1000813 ;
UPDATE script_texts SET content_loc4="把这些武器交给英雄们，助他们一臂之力。" WHERE entry=-1000814 ;
UPDATE script_texts SET content_loc4="痊愈吧！" WHERE entry=-1000815 ;
UPDATE script_texts SET content_loc4="我们得救了！农夫们逃脱了亡灵天灾的魔爪！" WHERE entry=-1000816 ;
UPDATE script_texts SET content_loc4="我再次失败了……" WHERE entry=-1000817 ;
UPDATE script_texts SET content_loc4="我现在就回去，我到这儿来无非是再次体验相同的悲惨遭遇罢了。" WHERE entry=-1000818 ;
UPDATE script_texts SET content_loc4="亡灵天灾来了！快跑啊！逃命吧！" WHERE entry=-1000819 ;
UPDATE script_texts SET content_loc4="请帮帮我们！王子发狂了！" WHERE entry=-1000820 ;
UPDATE script_texts SET content_loc4="去壁炉谷寻求庇护吧！那是我们惟一的希望！" WHERE entry=-1000821 ;
UPDATE script_texts SET content_loc4="我已经通知了温德索尔元帅。他应该很快就能赶到这儿。" WHERE entry=-1000822 ;
UPDATE script_texts SET content_loc4="嗷！" WHERE entry=-1000823 ;
UPDATE script_texts SET content_loc4="我知道你会来的，$n。很高兴再次见到你，朋友。" WHERE entry=-1000824 ;
UPDATE script_texts SET content_loc4="朋友，保持警惕。除非打一架，否则母龙是不会放弃的。" WHERE entry=-1000825 ;
UPDATE script_texts SET content_loc4="就像很久以前在卡拉赞注定的那样，怪物。我来了，带着公正的裁决而来！" WHERE entry=-1000826 ;
UPDATE script_texts SET content_loc4="抓住他！抓住这个卑鄙的罪犯和他的同伙！" WHERE entry=-1000827 ;
UPDATE script_texts SET content_loc4="雷吉纳德，你知道，我是不能让你通过的。" WHERE entry=-1000828 ;
UPDATE script_texts SET content_loc4="你一定要做你认为是正确的事情，马库斯。我们一起在图拉扬将军麾下服役。他使我们两个成为了今天的样子。他看错我了么？你真的相信我的目的是要破坏我们的联盟吗？我让我们的英雄们蒙羞了吗？" WHERE entry=-1000829 ;
UPDATE script_texts SET content_loc4="把我挡在这里可不是明智的决定，马库斯。" WHERE entry=-1000830 ;
UPDATE script_texts SET content_loc4="%s似乎陷入了沉思。" WHERE entry=-1000831 ;
UPDATE script_texts SET content_loc4="我很惭愧，老朋友。我不知道我该怎么办了。并不是你使那些伟大的英雄蒙羞，而是我。是我和其余堕落的政客们。他们让我们的生命中充满空洞的诺言和无尽的谎言。" WHERE entry=-1000832 ;
UPDATE script_texts SET content_loc4="我们令祖先蒙羞。我们令牺牲的同胞蒙羞……原谅我吧，雷吉纳德。" WHERE entry=-1000833 ;
UPDATE script_texts SET content_loc4="亲爱的朋友，你警惕的目光让英雄们以你为荣，你对联盟忠心耿耿。你会在必要的时候像那些俯瞰着你的英雄一样，为你的人民做出伟大的牺牲，我对此毫不怀疑。" WHERE entry=-1000834 ;
UPDATE script_texts SET content_loc4="现在是结束她统治的时候了，马库斯。让开，我的朋友。" WHERE entry=-1000835 ;
UPDATE script_texts SET content_loc4="退后！你们没看到英雄正在与我们同行吗？" WHERE entry=-1000836 ;
UPDATE script_texts SET content_loc4="让开！让他们过去！" WHERE entry=-1000837 ;
UPDATE script_texts SET content_loc4="雷吉纳德·温德索尔不得受到任何伤害！让他安全地通过这里！" WHERE entry=-1000838 ;
UPDATE script_texts SET content_loc4="去吧，雷吉纳德。愿光明指引着你。" WHERE entry=-1000839 ;
UPDATE script_texts SET content_loc4="谢谢你，老朋友。你做得好。" WHERE entry=-1000840 ;
UPDATE script_texts SET content_loc4="跟着我，朋友。到暴风城要塞！" WHERE entry=-1000841 ;
UPDATE script_texts SET content_loc4="愿圣光与您同在，长官。" WHERE entry=-1000842 ;
UPDATE script_texts SET content_loc4="我们不过是您脚下的尘土。" WHERE entry=-1000843 ;
UPDATE script_texts SET content_loc4="……瑟银的胆量。" WHERE entry=-1000844 ;
UPDATE script_texts SET content_loc4="让开！" WHERE entry=-1000845 ;
UPDATE script_texts SET content_loc4="一个活生生的传说……" WHERE entry=-1000846 ;
UPDATE script_texts SET content_loc4="我永远都会记住这一刻。" WHERE entry=-1000847 ;
UPDATE script_texts SET content_loc4="您对我们所有人都是一种激励，阁下。" WHERE entry=-1000848 ;
UPDATE script_texts SET content_loc4="朋友，勇敢些。这只爬虫会剧烈地翻滚起来。那是绝望的表现。你准备好了就跟我说一声。" WHERE entry=-1000849 ;
UPDATE script_texts SET content_loc4="前进！" WHERE entry=-1000850 ;
UPDATE script_texts SET content_loc4="国王陛下，请在一切还来得及的时候赶快退避一下吧。她并非你所想象的那样……" WHERE entry=-1000851 ;
UPDATE script_texts SET content_loc4="尊贵的陛下，请到安全的大厅去。" WHERE entry=-1000852 ;
UPDATE script_texts SET content_loc4="化妆舞会结束了，女伯爵普瑞斯托。或者我应该称呼你的真名……奥妮克希亚……" WHERE entry=-1000853 ;
UPDATE script_texts SET content_loc4="%s笑了。" WHERE entry=-1000854 ;
UPDATE script_texts SET content_loc4="你会被监禁并因叛国罪接受审判，温德索尔。我会很高兴看到他们宣布你有罪，并把你送上绞刑架……" WHERE entry=-1000855 ;
UPDATE script_texts SET content_loc4="当你瘫软的尸体在绞刑架上摇摆的时候，我会为一个疯子的性命终于得到终结而高兴。毕竟，你有什么证据呢？你难道想要到这里来挑衅一个贵族，然后毫发无伤地离开？" WHERE entry=-1000856 ;
UPDATE script_texts SET content_loc4="你逃脱不了你的命运，奥妮克希亚。预言早已注定了这一切——卡拉赞的大厅里浮现的幻景早已预示了你的结局。现在来做一个了结吧……" WHERE entry=-1000857 ;
UPDATE script_texts SET content_loc4="%s打开包裹，取出密文石板。" WHERE entry=-1000858 ;
UPDATE script_texts SET content_loc4="黑铁矮人认为这些石板是经过加密的。但这不是什么密码，只是古老的龙语而已。" WHERE entry=-1000859 ;
UPDATE script_texts SET content_loc4="听着，你这条龙。让真相大白于天下吧。" WHERE entry=-1000860 ;
UPDATE script_texts SET content_loc4="%s开始阅读石板。某种从未听过的神秘声音在你耳边回荡。" WHERE entry=-1000861 ;
UPDATE script_texts SET content_loc4="%s喘息着。" WHERE entry=-1000862 ;
UPDATE script_texts SET content_loc4="我好奇的是……温德索尔，在那个幻象中，你最终有没有活下来？我之所以这样问，是因为我可以确保你今天死定了。就是现在。" WHERE entry=-1000863 ;
UPDATE script_texts SET content_loc4="龙！卫兵！卫兵！抓住这个怪物！" WHERE entry=-1000864 ;
UPDATE script_texts SET content_loc4="对……卫兵们，过来帮帮你们的主人！" WHERE entry=-1000865 ;
UPDATE script_texts SET content_loc4="别让她逃了！" WHERE entry=-1000866 ;
UPDATE script_texts SET content_loc4="这是命运吗，温德索尔？如果你是赶来赴死的，那么预言已经实现了。愿你的思想在扭曲虚空里面腐烂。干掉其余爱管闲事的家伙，我的孩子们。伯瓦尔，你是一个令人满意的傀儡。" WHERE entry=-1000867 ;
UPDATE script_texts SET content_loc4="你们已经失败了，凡人……再见！" WHERE entry=-1000868 ;
UPDATE script_texts SET content_loc4="雷吉纳德……我……很抱歉。" WHERE entry=-1000869 ;
UPDATE script_texts SET content_loc4="伯……伯瓦尔……勋章……用它……" WHERE entry=-1000870 ;
UPDATE script_texts SET content_loc4="%s死了。" WHERE entry=-1000871 ;
