UPDATE script_texts SET content_loc4="很好，我们继续前进吧。" WHERE entry=-1000912 ;
UPDATE script_texts SET content_loc4="小心！我们受到攻击了！" WHERE entry=-1000913 ;
UPDATE script_texts SET content_loc4="一定是光明使者的印记所散发出的纯洁气息把天灾军团吸引来了。我们必须加倍小心！" WHERE entry=-1000914 ;
UPDATE script_texts SET content_loc4="又来了！小心！" WHERE entry=-1000915 ;
