UPDATE script_texts SET content_loc4="哦！这比我预料的要多得多了，你随便吧，干柴！" WHERE entry=-1000979 ;
UPDATE script_texts SET content_loc4="我要回去拿点东西，然后再去旅店里见你。" WHERE entry=-1000980 ;
