UPDATE script_texts SET content_loc4="做好准备。不要让这仪式被打断，否则我们会失去他……" WHERE entry=-1000982 ;
UPDATE script_texts SET content_loc4="小心。这个蠢货交给我来对付。" WHERE entry=-1000983 ;
