UPDATE script_texts SET content_loc4="你这个莽撞的家伙！你简直是自寻死路！看吧，你惊动了主人！" WHERE entry=-1409024 ;
UPDATE script_texts SET content_loc4="%s强迫一个火誓者爪牙爆炸！" WHERE entry=-1409025 ;
UPDATE script_texts SET content_loc4="恶魔逃脱了！我们必须尽快制止他！" WHERE entry=-1429000 ;
UPDATE script_texts SET content_loc4="谁敢破坏埃雷萨拉斯的圣洁？懦夫，面对我！" WHERE entry=-1429001 ;
