UPDATE script_texts SET content_loc4="我们不用再呆在这座石墙里面了！我们很快就能报仇了！在我们的怒火面前，就连那些龙也会战栗！" WHERE entry=-1509006 ;
UPDATE script_texts SET content_loc4="让敌人胆战心惊吧！让他们在恐惧中死去！" WHERE entry=-1509007 ;
UPDATE script_texts SET content_loc4="鹿盔将会呜咽着哀求我饶他一命，就像他那懦弱的儿子一样！一千年来的屈辱会在今天洗清！" WHERE entry=-1509008 ;
UPDATE script_texts SET content_loc4="范达尔！你的死期到了！藏到翡翠梦境里去吧，祈祷我们永远都找不到你！" WHERE entry=-1509009 ;
UPDATE script_texts SET content_loc4="无礼的蠢货！我会亲自要了你们的命！" WHERE entry=-1509010 ;
UPDATE script_texts SET content_loc4="攻击！让他们付出沉重代价！" WHERE entry=-1509011 ;
UPDATE script_texts SET content_loc4="粉碎他们！驱逐他们！" WHERE entry=-1509012 ;
UPDATE script_texts SET content_loc4="毫不犹豫！消灭他们！" WHERE entry=-1509013 ;
UPDATE script_texts SET content_loc4="战士们，军官们，继续战斗！" WHERE entry=-1509014 ;
UPDATE script_texts SET content_loc4="你真烦人，$n。" WHERE entry=-1509015 ;
UPDATE script_texts SET content_loc4="纳命来！" WHERE entry=-1509016 ;
UPDATE script_texts SET content_loc4="很快你就会知道多管闲事的后果了，凡人……我的主人很快就能恢复力量……当他站起来的时候，就是你的世界毁灭的时候。" WHERE entry=-1509017 ;
UPDATE script_texts SET content_loc4="我又恢复了活力！" WHERE entry=-1509018 ;
UPDATE script_texts SET content_loc4="我的力量恢复啦！" WHERE entry=-1509019 ;
UPDATE script_texts SET content_loc4="我的力量回来啦！" WHERE entry=-1509020 ;
