UPDATE script_texts SET content_loc4="你们玷污了这片神圣的土地，会因此受到惩罚的！上古之神的律法不容藐视！入侵者要付出生命的代价！" WHERE entry=-1531008 ;
UPDATE script_texts SET content_loc4="我宣判你死刑！" WHERE entry=-1531009 ;
UPDATE script_texts SET content_loc4="我战斗到了最后一刻！" WHERE entry=-1531010 ;
