UPDATE script_texts SET content_loc4="你的风度哪去了，兄弟？让我们欢迎这些客人吧。" WHERE entry=-1531014 ;
UPDATE script_texts SET content_loc4="你们会很痛苦……" WHERE entry=-1531015 ;
UPDATE script_texts SET content_loc4="哦，非常痛苦……" WHERE entry=-1531016 ;
